"""The browse shelves: hand-picked manga, podcasts and audiobooks with a few sentences on each.

These three trackers arrived in October 2026 with empty libraries, so there was nothing
for a visitor to add and nothing for a search engine to read. The shelves below are the
starting stock. Every entry is public knowledge (title, creator, year, format), the
"why" and "fit" lines are OmniTrackr's own, and nothing here is a member's rating.

Years: when a manga started serializing, when a podcast first aired, when a book
was first published. Volume counts are given only for finished series. Narrators
name the audiobook edition the shelf is talking about; other editions exist.

Keys are stable: a visitor's saved-before-sign-up list and the browse add endpoint
refer to them, so renaming one breaks links. Add new entries at the end of a shelf.
"""
from __future__ import annotations


def _m(key, title, author, year, genre, why, fit, volumes=None, chapters=None, status=None, kind=None):
    return {"key": key, "title": title, "creator": author, "year": year, "genre": genre, "why": why, "fit": fit,
            "extra": {"volumes": volumes, "chapters": chapters}, "status": status, "format": kind}


def _p(key, title, host, year, genre, why, fit, status=None):
    return {"key": key, "title": title, "creator": host, "year": year, "genre": genre, "why": why, "fit": fit,
            "extra": {}, "status": status, "format": None}


def _a(key, title, author, narrator, year, genre, hours, why, fit):
    return {"key": key, "title": title, "creator": author, "year": year, "genre": genre, "why": why, "fit": fit,
            "extra": {"narrator": narrator, "length_hours": hours}, "status": None, "format": None}


