def entries(kind: str) -> list[dict]:
    """Every shelf item for a kind, in page order."""
    return [item for shelf in CATALOG[kind]["shelves"] for item in shelf["items"]]


def find(kind: str, key: str) -> dict | None:
    for item in entries(kind):
        if item["key"] == key:
            return item
    return None
